INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'variables-data-types'), '70000000-0000-0000-0000-000000000001'::uuid, 'Why does ''byte b = 10; b = b + 1;'' fail to compile while ''b += 1;'' succeeds?', '{"A": "The + operator promotes byte operands to int, whereas += includes an implicit cast", "B": "1 is a double literal", "C": "+= uses bitwise addition", "D": "byte variables are immutable"}'::jsonb, 'A', 'Binary numeric promotion turns b + 1 into an int, which cannot be assigned back to byte without a cast; compound assignment += performs an implicit narrowing cast.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
