INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'variables-data-types'), '70000000-0000-0000-0000-000000000002'::uuid, 'Why is ''Integer.valueOf(100) == Integer.valueOf(100)'' true while ''Integer.valueOf(200) == Integer.valueOf(200)'' is false?', '{"A": "Java caches Integer objects for values -128 to 127", "B": "200 overflows Integer", "C": "200 triggers garbage collection", "D": "== compares values only up to 127"}'::jsonb, 'A', 'The IntegerCache caches instances in [-128, 127], so valueOf(100) returns the same object reference while valueOf(200) allocates distinct objects.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'variables-data-types'), '70000000-0000-0000-0000-000000000002'::uuid, 'When a reference variable is passed to a Java method, what is actually copied onto the callee''s stack frame?', '{"A": "Nothing; Java uses pass-by-reference", "B": "The memory address of the caller''s local variable", "C": "A copy of the reference value (pointer), not the object itself", "D": "A deep copy of the object"}'::jsonb, 'C', 'Java is strictly pass-by-value; for objects, the value passed is a copy of the reference pointing to the same heap object.', 'ADVANCED', TRUE);
