INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'variables-data-types'), '70000000-0000-0000-0000-000000000003'::uuid, 'In Java, why can ''char'' to ''short'' and ''short'' to ''char'' both require explicit casts?', '{"A": "Both are 16-bit, but char is unsigned (0..65535) and short is signed (-32768..32767)", "B": "char is 8-bit and short is 16-bit", "C": "char is a reference type", "D": "short cannot represent ASCII values"}'::jsonb, 'A', 'Neither range is a subset of the other: short allows negatives that char cannot hold, and char allows 32768..65535 that short cannot hold.', 'ADVANCED', TRUE);

