INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000004'::uuid, 'What is short-circuit evaluation in ''a != null && a.length() > 0''?', '{"A": "The expression throws an error if a is null", "B": "If a != null is false, a.length() > 0 is not evaluated, preventing NullPointerException", "C": "Both sides always execute", "D": "The right side executes first"}'::jsonb, 'B', '&& short-circuits when the left operand is false because the overall result is already guaranteed to be false.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000004'::uuid, 'How does ''&'' differ from ''&&'' when applied to boolean expressions?', '{"A": "& performs addition", "B": "&& is bitwise and & is logical", "C": "& always evaluates both operands (no short-circuiting), whereas && short-circuits", "D": "& is invalid on booleans"}'::jsonb, 'C', 'On booleans, & evaluates both sides eagerly, while && skips the right side if the left side is false.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000004'::uuid, 'What is the result of ''-7 % 3'' in Java?', '{"A": "1", "B": "2", "C": "-2", "D": "-1"}'::jsonb, 'D', 'In Java, the sign of the remainder matches the dividend (-7), so -7 % 3 == -1 because (-2 * 3) + (-1) == -7.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000005'::uuid, 'What is the value of ''x'' after: ''int x = 5; int y = x++ + ++x;''?', '{"A": "x=7, y=11", "B": "x=7, y=13", "C": "x=7, y=12", "D": "x=6, y=11"}'::jsonb, 'C', 'x++ evaluates to 5 (x becomes 6), then ++x increments x to 7 and evaluates to 7, so y = 5 + 7 = 12 and x = 7.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
