INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000006'::uuid, 'What does the bitwise AND expression ''6 & 3'' evaluate to?', '{"A": "2", "B": "1", "C": "5", "D": "7"}'::jsonb, 'A', '6 is 110 in binary and 3 is 011; 110 & 011 = 010 (decimal 2).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
