INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000006'::uuid, 'Can a ternary expression ''cond ? a : b'' be used as a standalone statement without assigning or returning its value?', '{"A": "Yes, if a and b are void", "B": "No, a ternary expression produces a value and is not a valid standalone statement", "C": "Yes, always", "D": "Yes, only inside loops"}'::jsonb, 'B', 'Unlike if-else, the ternary operator is an expression that must yield a value (not void methods) in a valid context.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
