INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000004'::uuid, 'Why does ''1 / 0'' throw ArithmeticException while ''1.0 / 0.0'' does not?', '{"A": "Both throw ArithmeticException", "B": "double division is unchecked at runtime", "C": "Java converts 0.0 to 1.0", "D": "Floating-point division by zero follows IEEE 754 and produces Infinity"}'::jsonb, 'D', 'Integer division by zero throws ArithmeticException, whereas IEEE 754 floating-point division by 0.0 yields Infinity (or NaN for 0.0/0.0).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000005'::uuid, 'In Java, if ''a'' is true, ''b'' is false, and ''c'' is true, what does ''a || b && c'' evaluate to and why?', '{"A": "true, because && has higher precedence than ||, so it parses as a || (b && c)", "B": "false, because || and && have equal precedence", "C": "Compile error due to ambiguity", "D": "true, because || has higher precedence than &&"}'::jsonb, 'A', '&& binds tighter than ||, so it evaluates as a || (b && c); since a is true, || short-circuits to true.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000005'::uuid, 'In ''int[] arr = {10, 20}; int i = 0; arr[i++] = arr[i] + 5;'', what is arr[0] after execution?', '{"A": "15", "B": "10", "C": "25", "D": "30"}'::jsonb, 'C', 'Java evaluates the left-hand side target before the right-hand side: arr[0] is selected and i becomes 1, then RHS reads arr[1] (20) + 5 = 25, assigning 25 to arr[0].', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000006'::uuid, 'How does ''>>>'' differ from ''>>'' in Java when shifting negative integers?', '{"A": ">>> throws an exception on negative numbers", "B": ">>> fills vacated high bits with 0 (unsigned), while >> preserves the sign bit", "C": ">>> shifts left, >> shifts right", "D": "There is no difference"}'::jsonb, 'B', '>>> is the unsigned/logical right shift (zero-extension), whereas >> is the signed/arithmetic right shift (sign-extension).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000006'::uuid, 'What is the type of the expression ''true ? Integer.valueOf(1) : Double.valueOf(2.0)'' in Java?', '{"A": "Object", "B": "Number", "C": "Integer", "D": "double (unboxed and widened)"}'::jsonb, 'D', 'When one branch is Integer and the other is Double, Java''s ternary binary numeric promotion unboxes both and promotes the result type to primitive double (yielding 1.0).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'operators-expressions'), '70000000-0000-0000-0000-000000000004'::uuid, 'Which bitwise expression efficiently tests whether a positive integer n is a power of two?', '{"A": "(n | (n - 1)) == 0", "B": "(n ^ n) == 1", "C": "(n & (n - 1)) == 0", "D": "(n & (n + 1)) == 0"}'::jsonb, 'C', 'A power of two has exactly one set bit; subtracting 1 flips all trailing zeros and clears that bit, so n & (n - 1) equals 0.', 'ADVANCED', TRUE);

-- Skill: conditional-statements
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'What type must the condition inside an ''if (...)'' statement evaluate to in Java?', '{"A": "String or boolean", "B": "int or boolean", "C": "boolean", "D": "Any non-zero value"}'::jsonb, 'C', 'Unlike C/C++, Java strictly requires a boolean expression inside an if statement; integers like 0 or 1 do not compile.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'In an ''if / else if / else'' chain, how many branches can execute during a single evaluation?', '{"A": "Only the else branch", "B": "All matching branches", "C": "At most one branch — the first whose condition is true", "D": "Always two branches"}'::jsonb, 'C', 'Once a matching condition is found, its block executes and the rest of the if-else-if chain is skipped.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'When is the ''else'' block executed in an if-else statement?', '{"A": "Only when the if condition (and any preceding else-if conditions) evaluate to false", "B": "When the if block throws an exception", "C": "Only if no return statement is used", "D": "Always after the if block"}'::jsonb, 'A', 'The else branch serves as the fallback when all preceding conditions are false.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'What keyword prevents execution from falling through to the next ''case'' in a classic Java switch statement?', '{"A": "stop", "B": "continue", "C": "break", "D": "exit"}'::jsonb, 'C', 'break exits the switch block; without it, control falls through into subsequent case labels.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'What is the purpose of the ''default'' label in a switch statement?', '{"A": "It resets the switch variable", "B": "It runs when none of the case values match", "C": "It runs before any case", "D": "It is mandatory in every switch"}'::jsonb, 'B', 'default acts as the catch-all branch when no case constant matches the switch selector.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'Which data type CANNOT be used as the selector in a Java switch statement?', '{"A": "enum", "B": "double", "C": "String", "D": "int"}'::jsonb, 'B', 'Java switch supports byte, short, char, int (and their wrappers), enum, and String (plus pattern types in newer Java), but not float or double.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'What is a nested ''if'' statement?', '{"A": "An if statement using ||", "B": "An if statement placed inside the body of another if or else block", "C": "An if statement with two else blocks", "D": "An if statement inside a switch default"}'::jsonb, 'B', 'Nesting places one conditional block inside another to check secondary conditions only after an outer condition holds.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'What is a guard clause in conditional logic?', '{"A": "A try-catch block around an if statement", "B": "An early return at the start of a method when an invalid/edge condition occurs", "C": "A mandatory default case", "D": "A deeply nested else block"}'::jsonb, 'B', 'Guard clauses handle edge or invalid cases early with a return/throw, reducing deep nesting.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'What happens if an ''if'' statement omits curly braces ''{ }'' and has two statements indented underneath it?', '{"A": "Neither statement executes", "B": "Both statements belong to the if", "C": "Compile-time error", "D": "Only the first statement is controlled by the if; the second always executes"}'::jsonb, 'D', 'Without braces, an if statement governs only the single statement immediately following it, regardless of indentation.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'Why does ''if (x = true)'' compile when x is a boolean, whereas ''if (y = 1)'' fails when y is an int?', '{"A": "int cannot be assigned inside parentheses", "B": "y = 1 is a syntax error", "C": "Assignment returns the assigned value: boolean is valid in if(), int is not", "D": "= means equality for booleans"}'::jsonb, 'C', 'An assignment expression evaluates to the assigned value; for boolean that is boolean (valid in if), whereas for int it is int (rejected by if).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'In a modern Java switch expression using arrow syntax (''case 1 -> ...''), does fall-through occur?', '{"A": "No, arrow cases never fall through", "B": "Only on the last case", "C": "Yes, unless break is written", "D": "Only for String selectors"}'::jsonb, 'A', 'Arrow-label switch rules (''->'') execute only the matched branch and do not fall through.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'What happens if you pass a null String reference into a classic Java ''switch (str)'' without a null case?', '{"A": "It matches an empty string case", "B": "It skips the switch silently", "C": "It executes the default branch", "D": "It throws NullPointerException"}'::jsonb, 'D', 'Switching on a null reference throws NullPointerException unless explicitly handled (e.g., Java 21 ''case null'').', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'In a Java switch expression that returns a value using a block ''{ ... }'', which keyword returns the value from that branch?', '{"A": "return", "B": "output", "C": "yield", "D": "break"}'::jsonb, 'C', 'yield produces the value for a block branch inside a switch expression.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'Why must switch case values be compile-time constants?', '{"A": "Because variables cannot be compared", "B": "To prevent garbage collection", "C": "To allow the compiler to validate uniqueness and generate jump/lookup tables", "D": "Because switch only works with static fields"}'::jsonb, 'C', 'Switch requires constant expressions so the compiler can detect duplicate cases and optimize dispatch (tableswitch/lookupswitch).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'In the dangling-else problem (''if (a) if (b) x(); else y();''), which ''if'' does ''else y();'' bind to?', '{"A": "Both if statements", "B": "The outer ''if (a)''", "C": "Compile error", "D": "The nearest preceding unmatched ''if (b)''"}'::jsonb, 'D', 'Java binds an else clause to the innermost unmatched if statement.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'How can you refactor a 4-level nested if-else chain into cleaner code?', '{"A": "Use guard clauses with early returns or combine independent conditions", "B": "Use goto statements", "C": "Add more else blocks", "D": "Replace every if with a while loop"}'::jsonb, 'A', 'Early-return guard clauses flatten the control flow and improve readability.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'Which condition is logically equivalent to ''!(a && b)'' according to De Morgan''s Law?', '{"A": "!a && !b", "B": "!a || !b", "C": "!a ^ !b", "D": "a || b"}'::jsonb, 'B', 'De Morgan''s Law states !(a && b) == (!a || !b).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'When comparing two String variables in an if-condition for value equality, which should be used?', '{"A": "s1 = s2", "B": "Objects.equals(s1, s2) or s1.equals(s2)", "C": "s1 == s2", "D": "s1 != s2"}'::jsonb, 'B', '== compares object references, while .equals() / Objects.equals() compares character contents safely.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'What requirement applies when using a switch expression to assign a value to a variable?', '{"A": "It must be exhaustive (cover all possible input values, usually via default)", "B": "It must contain at least 3 cases", "C": "Every case must end with break", "D": "It cannot use enums"}'::jsonb, 'A', 'A switch expression must produce a value for every possible selector value; non-exhaustive switches fail to compile.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'Why is ''switch'' on dense consecutive integer cases often faster than a long ''if-else if'' chain in bytecode?', '{"A": "JVM compiles dense switches to a tableswitch instruction with O(1) jump-table lookup", "B": "if-else allocates heap objects", "C": "switch runs on a separate thread", "D": "switch bypasses CPU branch prediction"}'::jsonb, 'A', 'javac emits a tableswitch (O(1) indexed jump) for dense cases or lookupswitch (O(log n) binary search) for sparse cases.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'Given ''if (a) { if (b) return 1; } else return 2;'', under what condition does the method fall through without returning?', '{"A": "Never; all paths return", "B": "When a is true and b is true", "C": "When a is true and b is false", "D": "When a is false"}'::jsonb, 'C', 'If a is true and b is false, the inner if is skipped and the outer else is skipped, so control falls through.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000007'::uuid, 'In Java, why can ''if (CONSTANT_FALSE) { ... }'' compile without an ''unreachable code'' error, unlike ''while (false) { ... }''?', '{"A": "while(false) is a runtime error", "B": "Both fail with unreachable code", "C": "if(false) is always executed once", "D": "Java treats if(false) specially to support conditional compilation flags"}'::jsonb, 'D', 'The Java Language Specification explicitly permits unreachable then/else blocks in ''if'' to allow compile-time debug flags.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000008'::uuid, 'What happens if two case labels in the same Java switch evaluate to the same constant value (e.g., ''case 65:'' and ''case ''''A'''':'')?', '{"A": "The first one wins at runtime", "B": "Compile-time error: duplicate case label", "C": "Both execute in sequence", "D": "Only ''A'' matches"}'::jsonb, 'B', 'char ''A'' has numeric value 65, so the compiler rejects duplicate case constants.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'conditional-statements'), '70000000-0000-0000-0000-000000000009'::uuid, 'Why should null-checks precede method-call checks in compound conditions like ''if (user != null && user.isActive())''?', '{"A": "Java requires null checks first syntactically", "B": "Left-to-right short-circuiting guarantees user.isActive() is never invoked on null", "C": "user.isActive() returns null otherwise", "D": "&& evaluates right-to-left"}'::jsonb, 'B', 'Because && evaluates left-to-right and short-circuits on false, placing user != null first prevents NullPointerException.', 'ADVANCED', TRUE);

-- Skill: loops
