INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'What are the three header parts of a standard Java ''for (init; condition; update)'' loop?', '{"A": "Declaration, exception, return", "B": "Start, break, continue", "C": "Type, variable, array", "D": "Initialization, termination condition, increment/update"}'::jsonb, 'D', 'The three clauses control initialization (once), loop condition (before each iteration), and update (after each iteration).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'Which loop syntax is best for iterating over every element of an array when the index is not needed?', '{"A": "do-while", "B": "switch-case", "C": "Infinite while(true)", "D": "Enhanced for-each loop: for (T item : array)"}'::jsonb, 'D', 'The enhanced for-each loop cleanly traverses arrays and Iterables without manual index management.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000011'::uuid, 'What does the ''break'' statement do inside a loop?', '{"A": "Restarts the loop from index 0", "B": "Skips only the current iteration", "C": "Exits the entire JVM", "D": "Immediately terminates the enclosing loop"}'::jsonb, 'D', 'break exits the innermost enclosing loop (or switch) and resumes execution after it.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000011'::uuid, 'What does the ''continue'' statement do inside a loop?', '{"A": "Skips the remainder of the current iteration and moves to the next iteration", "B": "Terminates the loop permanently", "C": "Exits the method", "D": "Pauses the loop for 1 second"}'::jsonb, 'A', 'continue jumps to the next iteration of the enclosing loop (evaluating the update/condition).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
