VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'In ''for (int i = 0; i < 5; i++)'', what is the scope of variable ''i''?', '{"A": "Global across packages", "B": "Only inside the for loop header and body", "C": "The entire enclosing method", "D": "The entire class"}'::jsonb, 'B', 'A loop variable declared in the for-header is scoped strictly to that for statement.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'What happens if you modify the loop variable inside an enhanced for-each loop (''for (int x : arr) { x = 0; }'')?', '{"A": "ArrayIndexOutOfBoundsException", "B": "Only the local copy ''x'' changes; the array remains unchanged", "C": "The array elements become 0", "D": "Compile-time error"}'::jsonb, 'B', 'In a for-each loop over primitives, x is a local copy of each element, so reassigning x does not mutate the array.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'When should you prefer a ''while'' loop over a ''for'' loop?', '{"A": "When iterating an array by index", "B": "When the number of iterations is unknown beforehand and depends on a dynamic condition", "C": "When you want faster execution", "D": "When you need a loop to run at least once"}'::jsonb, 'B', 'while loops express open-ended repetition (e.g., reading until EOF or convergence) more naturally than for loops.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000011'::uuid, 'In a ''while'' loop, if ''continue'' executes before the loop counter increment statement, what risk occurs?', '{"A": "An infinite loop, because the counter never updates", "B": "The loop terminates early", "C": "The counter increments twice", "D": "Compile-time error"}'::jsonb, 'A', 'Skipping the manual counter update in a while loop can leave the condition permanently true, causing an infinite loop (unlike a for loop whose update clause still runs).', 'INTERMEDIATE', TRUE);
