VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'Why is ''for ( ; ; )'' valid syntax in Java?', '{"A": "It runs zero times", "B": "It iterates once", "C": "All three clauses in a for-header are optional, creating an infinite loop until broken", "D": "It is a syntax error"}'::jsonb, 'C', 'An empty condition in a for-loop defaults to true, making for(;;) an infinite loop.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'What happens if you remove an element from an ArrayList inside an enhanced for-each loop?', '{"A": "The loop restarts", "B": "Compile-time error", "C": "It removes cleanly", "D": "ConcurrentModificationException is thrown by the underlying Iterator"}'::jsonb, 'D', 'The enhanced for-each loop uses an Iterator under the hood; structural modification directly on the list invalidates fail-fast modCount and throws ConcurrentModificationException.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000010'::uuid, 'Why can using a ''float'' or ''double'' as a loop counter (e.g., for (double d = 0.0; d != 1.0; d += 0.1)) cause an infinite loop?', '{"A": "doubles cannot be incremented", "B": "Floating-point rounding means d may never equal exactly 1.0", "C": "!= is invalid on doubles", "D": "d overflows at 1.0"}'::jsonb, 'B', '0.1 cannot be represented exactly in binary floating-point, so repeated addition accumulates tiny rounding error and skips 1.0.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000011'::uuid, 'How does ''continue outer;'' differ from ''break outer;'' inside a nested loop?', '{"A": "continue outer restarts the inner loop", "B": "Both exit the outer loop", "C": "Java does not support labeled continue", "D": "continue outer skips to the next iteration of the outer loop; break outer exits the outer loop completely"}'::jsonb, 'D', 'Labeled continue advances the named outer loop to its next iteration, whereas labeled break terminates it.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000012'::uuid, 'If a nested loop searches a 2D matrix for a target value and uses ''return true;'' upon finding it, why is that cleaner than ''break;''?', '{"A": "return is faster than break", "B": "break cannot be used in 2D arrays", "C": "break only exits the inner loop, requiring a flag or label to exit the outer loop; return exits immediately", "D": "return skips stack unwinding"}'::jsonb, 'C', 'Extracting the search into a helper method and returning immediately avoids extra boolean flags or labeled breaks.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000012'::uuid, 'What is the time complexity of: ''for (int i = 1; i < n; i *= 2) for (int j = 0; j < n; j++)''?', '{"A": "O(n)", "B": "O(n log n)", "C": "O(log n)", "D": "O(n^2)"}'::jsonb, 'B', 'The outer loop doubles i each step (log2(n) iterations) and the inner loop runs n times each, giving O(n log n).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'loops'), '70000000-0000-0000-0000-000000000011'::uuid, 'If a ''finally'' block executes after a ''break'' or ''continue'' inside a try block within a loop, when does it run?', '{"A": "The finally block always runs before control transfers out of the try block", "B": "Only if an exception is thrown", "C": "Never; break skips finally", "D": "Only on continue, not break"}'::jsonb, 'A', 'Java guarantees finally executes whenever control leaves a try block, including via break, continue, or return.', 'ADVANCED', TRUE);

-- Skill: methods-functions
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'What is the difference between a method''s parameter and an argument?', '{"A": "Arguments are always Strings", "B": "They are unrelated", "C": "A parameter is the variable in the method declaration; an argument is the actual value passed at the call site", "D": "Parameters are only for static methods"}'::jsonb, 'C', 'Parameters define what inputs a method accepts; arguments are the concrete values supplied when invoking it.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'How do you declare a variable-arity (varargs) int parameter in Java?', '{"A": "int[]... nums", "B": "...int nums", "C": "int... nums", "D": "varargs int nums"}'::jsonb, 'C', 'Varargs syntax places three dots after the type (int... nums) and must be the last parameter.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'Does Java pass primitive arguments by value or by reference?', '{"A": "By reference", "B": "Depends on the JVM", "C": "By pointer", "D": "By value (a copy of the primitive is passed)"}'::jsonb, 'D', 'Java always passes arguments by value; modifying a primitive parameter inside a method does not change the caller''s variable.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'Which return type indicates that a Java method does not return any value?', '{"A": "null", "B": "void", "C": "empty", "D": "none"}'::jsonb, 'B', 'void specifies that the method returns no value.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'What happens when a ''return'' statement executes in a non-void method?', '{"A": "The method immediately exits and passes the return value back to the caller", "B": "It restarts the method", "C": "The method continues running remaining lines", "D": "It pauses execution"}'::jsonb, 'A', 'return immediately terminates the current method invocation and delivers the result to the caller.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'Can a ''void'' method contain a ''return;'' statement with no expression?', '{"A": "Only inside main()", "B": "Yes, to exit the method early", "C": "Only if it returns null", "D": "No, compile error"}'::jsonb, 'B', 'A bare ''return;'' is legal in void methods for early exit.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'What is method overloading in Java?', '{"A": "Writing two methods with the same name and same parameter list in one class", "B": "Calling a method too many times", "C": "Overriding a parent method", "D": "Defining multiple methods with the same name but different parameter lists in the same class"}'::jsonb, 'D', 'Overloading allows multiple methods with the same name as long as their parameter types, count, or order differ.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'What is recursion?', '{"A": "Returning two values from a method", "B": "A method that calls itself with a base case to terminate", "C": "A loop inside a method", "D": "Overloading a constructor"}'::jsonb, 'B', 'A recursive method solves a problem by calling itself on smaller subproblems until reaching a base case.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'How many varargs parameters can a single Java method have, and where must it appear?', '{"A": "At most one, and it must be the first parameter", "B": "Multiple, anywhere", "C": "At most one, and it must be the last parameter", "D": "Up to two"}'::jsonb, 'C', 'Java allows only one varargs parameter per method, positioned at the very end of the parameter list.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'Inside a method with parameter ''StringBuilder sb'', why does ''sb.append("hi")'' affect the caller''s object while ''sb = new StringBuilder()'' does not?', '{"A": "Java passes StringBuilder by reference", "B": "sb.append mutates the shared heap object; reassigning sb only changes the local parameter copy", "C": "StringBuilder is primitive", "D": "new StringBuilder() is blocked"}'::jsonb, 'B', 'The copied reference points to the same heap object (so mutations are visible), but reassigning the local parameter only rebinds the local copy.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'What type does a varargs parameter ''String... args'' actually compile to inside the method body?', '{"A": "List<String>", "B": "Object", "C": "Set<String>", "D": "String[]"}'::jsonb, 'D', 'The compiler treats ''String... args'' as a ''String[]'' array inside the method.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'What happens if a non-void method has an ''if'' branch that returns a value, but no return statement when the ''if'' condition is false?', '{"A": "Compile-time error: missing return statement", "B": "It returns null or 0 automatically", "C": "Runtime exception", "D": "It returns void"}'::jsonb, 'A', 'Every possible execution path in a non-void method must either return a compatible value or throw an exception.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'Can a method return a ''byte'' value if its declared return type is ''int''?', '{"A": "Only if static", "B": "Yes, via implicit widening conversion", "C": "No, types must match identically", "D": "Only with an explicit cast"}'::jsonb, 'B', 'A method can return any expression that is assignment-compatible with its return type, including widening byte -> int.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'Can two methods in the same class differ ONLY by their return type (e.g., ''int foo()'' and ''double foo()'')?', '{"A": "No, return type alone is not part of the method signature for overloading", "B": "Yes, if one is static", "C": "Yes, that is valid overloading", "D": "Yes, if they throw different exceptions"}'::jsonb, 'A', 'Overload resolution uses method name and parameter list only; differing solely by return type causes a duplicate method compile error.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'What error occurs at runtime if a recursive method has no reachable base case?', '{"A": "StackOverflowError", "B": "OutOfMemoryError", "C": "ArithmeticException", "D": "Infinite loop with no error"}'::jsonb, 'A', 'Each recursive call pushes a frame onto the call stack until the thread''s stack space is exhausted, throwing StackOverflowError.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'Which method is called when invoking ''print(5)'' if a class defines both ''print(long x)'' and ''print(Integer x)''?', '{"A": "Neither", "B": "print(long x)", "C": "Compile error: ambiguous", "D": "print(Integer x)"}'::jsonb, 'B', 'Java overload resolution prefers primitive widening (int -> long) before boxing (int -> Integer).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'Does changing parameter names (''void f(int a)'' vs ''void f(int b)'') create a valid overload?', '{"A": "Only for public methods", "B": "Yes", "C": "No, parameter names are ignored in method signatures", "D": "Only in interfaces"}'::jsonb, 'C', 'Method signatures consist of method name and parameter types, not parameter names.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'Why is returning an empty collection (e.g., Collections.emptyList()) often preferred over returning null?', '{"A": "Empty collections use no memory", "B": "Empty collections are faster to serialize", "C": "Callers can iterate directly without null checks, reducing NullPointerException bugs", "D": "null cannot be returned from List methods"}'::jsonb, 'C', 'Returning empty collections avoids defensive null checks at every call site.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'Given ''void m(int a, long b)'' and ''void m(long a, int b)'', what happens when calling ''m(1, 2)''?', '{"A": "Calls m(long, int)", "B": "Compile-time error: reference to m is ambiguous", "C": "Throws runtime exception", "D": "Calls m(int, long)"}'::jsonb, 'B', 'Neither overload is more specific than the other for two int arguments, so javac rejects the call as ambiguous.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'In overload resolution, what is the priority order Java uses to match a primitive argument?', '{"A": "Autoboxing -> Exact -> Varargs -> Widening", "B": "Exact match -> Primitive widening -> Autoboxing -> Varargs", "C": "Exact -> Varargs -> Widening -> Autoboxing", "D": "Varargs -> Boxing -> Widening -> Exact"}'::jsonb, 'B', 'Java resolves overloads in phases: (1) exact/widening without boxing/varargs, (2) boxing/unboxing, (3) varargs.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'Given ''void f(int... a)'' and ''void f(int x, int... a)'', what happens when calling ''f(1)''?', '{"A": "Calls f(int... a)", "B": "Compile-time error: reference to f is ambiguous", "C": "Throws IllegalArgumentException", "D": "Calls f(int x, int... a)"}'::jsonb, 'B', 'Both varargs methods match f(1), and neither is strictly more specific under varargs rules, causing ambiguity.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000014'::uuid, 'Does the standard HotSpot JVM automatically perform tail-call optimization (TCO) on tail-recursive Java methods?', '{"A": "Yes, if marked @TailRec", "B": "Only for void methods", "C": "Yes, always", "D": "No; deep tail recursion in Java can still cause StackOverflowError"}'::jsonb, 'D', 'Unlike languages such as Scala or Scheme, standard HotSpot/Java does not guarantee tail-call elimination, so convert deep recursion to iteration.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000013'::uuid, 'If a method declares ''void process(Object o)'' and ''void process(String s)'', which overload is chosen for ''process(null)''?', '{"A": "process(String), because String is a more specific subtype of Object", "B": "Compile error: ambiguous", "C": "process(Object)", "D": "NullPointerException"}'::jsonb, 'A', 'When multiple overloads match null, Java selects the most specific type in the inheritance hierarchy (String < Object).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'methods-functions'), '70000000-0000-0000-0000-000000000015'::uuid, 'Why can overloading ''void log(List<String> list)'' and ''void log(List<Integer> list)'' in the same class fail to compile?', '{"A": "Generics cannot be used in parameters", "B": "Type erasure erases both parameters to raw List, producing identical signatures", "C": "They return void", "D": "List cannot hold Integer"}'::jsonb, 'B', 'After generic type erasure, both methods have the exact same erasure ''log(List)'', which is illegal.', 'ADVANCED', TRUE);

