INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000016'::uuid, 'Can a Java array change its length after it has been created?', '{"A": "Yes, via resize()", "B": "Yes, if declared without final", "C": "Only for Object[]", "D": "No, array length is fixed upon creation"}'::jsonb, 'D', 'Arrays have fixed capacity once allocated; use ArrayList for dynamic resizing.', 'BEGINNER', TRUE);
