INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000017'::uuid, 'What does '' "hello".toUpperCase() '' do to the original String variable if you don''t assign the return value?', '{"A": "Sets the original String to null", "B": "Throws UnsupportedOperationException", "C": "Returns a new String \"HELLO\" while leaving the original unchanged", "D": "Modifies the original String in-place"}'::jsonb, 'C', 'Strings in Java are immutable; transformation methods always return a new String instance.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
