INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000018'::uuid, 'Why is StringBuilder preferred over String ''+'' concatenation inside a loop?', '{"A": "String ''+'' fails inside loops", "B": "StringBuilder mutates an internal buffer instead of creating a new String object on every iteration", "C": "StringBuilder is immutable", "D": "StringBuilder is thread-safe"}'::jsonb, 'B', 'Repeated ''+'' in a loop allocates O(n^2) intermediate String characters, whereas StringBuilder appends in amortized O(1).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
