INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000016'::uuid, 'What does ''Arrays.toString(arr)'' print compared to ''System.out.println(arr)''?', '{"A": "Both print elements", "B": "Arrays.toString sorts the array first", "C": "println(arr) throws an exception", "D": "Arrays.toString prints readable elements like [1, 2]; println(arr) prints the default Object type@hashCode"}'::jsonb, 'D', 'Arrays do not override Object.toString(), so printing an array directly outputs ''[I@...'' instead of its contents.', 'INTERMEDIATE', TRUE);
