INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000016'::uuid, 'What is a jagged (ragged) 2D array in Java?', '{"A": "A 2D array of primitives", "B": "A 2D array where each inner row array can have a different length", "C": "An unsorted array", "D": "An array with negative indices"}'::jsonb, 'B', 'In Java, a 2D array is an array of array references, so each row can be allocated with its own distinct length.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
