INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000017'::uuid, 'Why does ''"abc" == new String("abc")'' evaluate to false?', '{"A": "Different characters", "B": "== compares object references: the literal is in the String Pool while ''new String'' creates a distinct heap object", "C": "String does not support ==", "D": "new String creates an empty string"}'::jsonb, 'B', 'Use .equals() for value comparison; ''new String(...)'' forces a separate object outside the interned pool reference.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000017'::uuid, 'What does ''"a.b.c".split(".")'' return in Java and why?', '{"A": "[\"a\", \"b\", \"c\"]", "B": "Throws PatternSyntaxException", "C": "[\"a.b.c\"]", "D": "An empty array, because ''.'' in regex matches any character"}'::jsonb, 'D', 'split() takes a regex, where ''.'' matches every character; you must escape it as "\\.".', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000018'::uuid, 'How does StringBuilder differ from StringBuffer?', '{"A": "StringBuffer is synchronized (thread-safe); StringBuilder is unsynchronized and faster for single-threaded use", "B": "StringBuilder only works with ASCII", "C": "StringBuffer is immutable", "D": "StringBuilder is synchronized; StringBuffer is not"}'::jsonb, 'A', 'StringBuffer synchronizes its methods, adding overhead; StringBuilder is the non-synchronized drop-in replacement.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000018'::uuid, 'What is the default initial character capacity of ''new StringBuilder()''?', '{"A": "32", "B": "16", "C": "64", "D": "0"}'::jsonb, 'B', 'An empty StringBuilder allocates a default internal capacity of 16 characters before resizing.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000018'::uuid, 'Which StringBuilder method reverses its character sequence in-place?', '{"A": "Collections.reverse(sb)", "B": "reverse()", "C": "invert()", "D": "flip()"}'::jsonb, 'B', 'StringBuilder.reverse() reverses the characters in-place and returns ''this''.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000016'::uuid, 'Which utility method creates a shallow copy of an array with a specified new length?', '{"A": "Arrays.copyOf(arr, newLength)", "B": "Arrays.duplicate()", "C": "Arrays.clone()", "D": "System.cloneArray()"}'::jsonb, 'A', 'Arrays.copyOf allocates a new array of newLength and copies elements (truncating or padding with defaults).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000017'::uuid, 'Why did Java design String to be immutable?', '{"A": "To allow String Pool interning, thread safety, safe hashCode caching (e.g. HashMap keys), and security", "B": "To disable garbage collection", "C": "Because char[] cannot be mutated in JVM", "D": "To force developers to use StringBuilder"}'::jsonb, 'A', 'Immutability guarantees safe sharing in the String Pool, thread-safe access, cached hashCodes for HashMap/HashSet, and safe security parameters (URLs, paths).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000017'::uuid, 'What does calling ''str.intern()'' do in Java?', '{"A": "Makes a String mutable", "B": "Returns the canonical String reference from the String Pool (adding it if absent)", "C": "Converts str to UTF-8 bytes", "D": "Deletes str from memory"}'::jsonb, 'B', 'intern() ensures only one canonical instance for equal contents is returned from the String Pool.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000016'::uuid, 'What happens at runtime if you assign an Integer into a ''Number[] arr = new Double[2];'' array?', '{"A": "Converts Integer to Double", "B": "Throws ArrayStoreException at runtime", "C": "Compile-time error", "D": "Succeeds because Integer is a Number"}'::jsonb, 'B', 'Java arrays are covariant (Double[] is-a Number[]), so the compiler allows it, but the JVM checks the actual array element type at runtime and throws ArrayStoreException.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000016'::uuid, 'How does ''Arrays.equals(a, b)'' behave on 2D arrays (int[][])?', '{"A": "Deeply compares all inner elements", "B": "Compares outer element references using ==/equals; use Arrays.deepEquals() for nested arrays", "C": "Sorts both arrays first", "D": "Throws ClassCastException"}'::jsonb, 'B', 'Arrays.equals only performs a shallow comparison on nested arrays; Arrays.deepEquals recursively compares multi-dimensional arrays.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000018'::uuid, 'In modern Java (JDK 9+), how does the compiler optimize simple single-expression concatenation like ''s = a + b + c;''?', '{"A": "It refuses to compile without StringBuilder", "B": "It uses invokedynamic (StringConcatFactory) to size and build the result efficiently", "C": "It still creates 3 StringBuilders", "D": "It interns every intermediate string"}'::jsonb, 'B', 'Single-expression ''+'' uses StringConcatFactory via invokedynamic, though inside a loop you should still use StringBuilder explicitly.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'arrays-strings'), '70000000-0000-0000-0000-000000000017'::uuid, 'Why is ''new String("abc")'' generally discouraged compared to ''"abc"''?', '{"A": "It creates a mutable String", "B": "It bypasses UTF-16 encoding", "C": "It fails to compile in Java 21", "D": "It unnecessarily allocates an extra heap String object beyond the String Pool literal"}'::jsonb, 'D', 'The literal "abc" is already interned; wrapping it in ''new String(...)'' forces an extra object allocation.', 'ADVANCED', TRUE);

-- Skill: classes-objects
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'What is the relationship between a class and an object in Java?', '{"A": "An object is a static method", "B": "They are identical", "C": "A class is the blueprint/template; an object is a concrete instance created from that class", "D": "A class is created at runtime with ''new''"}'::jsonb, 'C', 'A class defines fields and methods; ''new'' instantiates objects with their own state on the heap.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'Which keyword is used to instantiate a new object from a class?', '{"A": "init", "B": "instance", "C": "new", "D": "create"}'::jsonb, 'C', 'The ''new'' operator allocates memory on the heap and invokes a constructor.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'What are instance variables (fields)?', '{"A": "Method parameters", "B": "Variables declared inside a class (outside methods) belonging to each object instance", "C": "Loop counters", "D": "Variables declared inside a method"}'::jsonb, 'B', 'Each object instance gets its own copy of non-static instance fields.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'What must a constructor''s name match in Java?', '{"A": "The package name", "B": "The name ''constructor''", "C": "The exact name of its enclosing class", "D": "Any camelCase name"}'::jsonb, 'C', 'A constructor must have the exact same name as its class and has no return type (not even void).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'When does Java automatically provide a default no-argument constructor?', '{"A": "Never", "B": "Only for abstract classes", "C": "Only when the class declares NO explicit constructors at all", "D": "Always, even if you write other constructors"}'::jsonb, 'C', 'If you define any parameterized constructor, the compiler does NOT generate a no-arg constructor unless you declare it explicitly.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'Can a Java class have multiple constructors with different parameter lists?', '{"A": "No, only one constructor is allowed", "B": "Only in subclasses", "C": "Yes, via constructor overloading", "D": "Only if one is private"}'::jsonb, 'C', 'Constructor overloading lets a class provide multiple ways to initialize objects.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'What does the ''this'' keyword refer to inside an instance method or constructor?', '{"A": "The current object instance on which the method/constructor is executing", "B": "The first parameter", "C": "The parent class", "D": "The static class definition"}'::jsonb, 'A', '''this'' is a reference to the current object, commonly used to disambiguate fields from parameters.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'How is a ''static'' variable shared across objects of a class?', '{"A": "Only one copy exists for the entire class, shared by all instances", "B": "Static variables cannot be modified", "C": "Each object gets a separate copy", "D": "Static variables are deleted after construction"}'::jsonb, 'A', 'static members belong to the class itself rather than individual instances.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'What happens if you give a constructor a ''void'' return type (''public void User()'')?', '{"A": "Java treats it as an ordinary method named User, NOT a constructor", "B": "It runs only for static calls", "C": "It still acts as a constructor", "D": "Compile-time error"}'::jsonb, 'A', 'Adding a return type turns it into a regular method; it will not run during ''new User()''.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'In what order are an object''s instance fields initialized relative to its constructor body?', '{"A": "Constructor body runs first, then field initializers", "B": "Field initializers and instance initializer blocks run in textual order BEFORE the constructor body", "C": "They run in parallel", "D": "Fields are initialized only after the constructor finishes"}'::jsonb, 'B', 'After super(), instance field initializers and instance initializer blocks execute before the constructor''s statements.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'What is constructor chaining using ''this(...)''?', '{"A": "Returning ''this'' from a method", "B": "Calling a parent class constructor", "C": "Calling another overloaded constructor in the same class; it must be the first statement", "D": "Calling a static method from a constructor"}'::jsonb, 'C', '''this(...)'' delegates initialization to another constructor in the same class and must be the very first statement.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'Why might a class declare its constructor ''private''?', '{"A": "To make fields public", "B": "To cause a compile error", "C": "To enable multiple inheritance", "D": "To prevent external ''new'' instantiation (e.g., Singleton, factory methods, or utility classes)"}'::jsonb, 'D', 'Private constructors restrict object creation to static factory methods or prevent instantiation in utility classes like Math.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'Why can a ''static'' method NOT directly access non-static instance fields or use ''this''?', '{"A": "Static methods belong to the class and execute without any object instance", "B": "JVM forbids reading fields in static methods", "C": "Static methods are slower", "D": "Instance fields are private"}'::jsonb, 'A', 'Without an instance, there is no ''this'' reference to resolve instance fields or instance methods.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'When does a ''static { ... }'' initialization block execute?', '{"A": "Every time ''new'' is called", "B": "Only when garbage collected", "C": "After main() finishes", "D": "Once when the class is first loaded/initialized by the JVM"}'::jsonb, 'D', 'Static initializers run once during class initialization before any static member is accessed or instance is created.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'What is the best practice for accessing static fields or methods?', '{"A": "Via super.count", "B": "Via this.count", "C": "Via the class name (ClassName.count)", "D": "Via an object reference (obj.count)"}'::jsonb, 'C', 'Using ClassName.member clearly communicates that the member is class-level and avoids misleading NullPointerException impressions.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'What happens to an object on the heap when no active references point to it anymore?', '{"A": "It becomes eligible for Garbage Collection", "B": "It stays in memory forever", "C": "It throws MemoryLeakException", "D": "It is deleted immediately at the closing brace"}'::jsonb, 'A', 'Objects unreachable from GC roots become eligible for automatic reclamation by the JVM Garbage Collector.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'Can a constructor call an instance method of the same class?', '{"A": "Yes, though calling overridable methods from a constructor is risky because subclass fields aren''t initialized yet", "B": "Only in final classes", "C": "Only if the method is static", "D": "No"}'::jsonb, 'A', 'Calling non-final/overridable methods in a constructor can expose partially constructed subclass state.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'What does ''return this;'' enable when used in setter or builder methods?', '{"A": "Static dispatch", "B": "Thread synchronization", "C": "Method chaining (fluent API style)", "D": "Garbage collection"}'::jsonb, 'C', 'Returning ''this'' lets callers chain calls like builder.name("A").age(25).build().', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'Can a constructor use both ''this(...)'' and ''super(...)'' in the same constructor?', '{"A": "Yes", "B": "Yes, if super() is second", "C": "Only in abstract classes", "D": "No, both must be the first statement, so a constructor can call at most one of them"}'::jsonb, 'D', 'Because both this(...) and super(...) must appear as the first statement, they are mutually exclusive.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'If class A has a static block, an instance initializer block, and a constructor, and you instantiate A twice (''new A(); new A();''), how many times does each run?', '{"A": "Static: 1, Instance: 1, Constructor: 2", "B": "Static: 2, Instance: 2, Constructor: 2", "C": "Static: 1, Instance: 2, Constructor: 2", "D": "Static: 2, Instance: 1, Constructor: 2"}'::jsonb, 'C', 'The static block runs once on class initialization; the instance block and constructor run once per ''new A()''.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'What happens if you call a static method through a null reference: ''MyClass ref = null; ref.staticMethod();''?', '{"A": "Returns null", "B": "Compile-time error", "C": "Succeeds without exception because static calls bind to the compile-time class type, not the runtime object", "D": "Throws NullPointerException"}'::jsonb, 'C', 'Static method calls are resolved at compile time using the reference''s declared type (invokestatic), never dereferencing ''ref''.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000019'::uuid, 'If a class overrides equals() but fails to override hashCode(), what breaks?', '{"A": "toString() throws an exception", "B": "Compilation fails", "C": "== stops working", "D": "Equal objects may produce different hash codes, breaking HashMap and HashSet lookups"}'::jsonb, 'D', 'The general contract requires equal objects (a.equals(b)) to have identical hashCodes; violating this corrupts hash-based collections.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000020'::uuid, 'In Java, what happens when a constructor throws a checked exception?', '{"A": "The JVM ignores the exception", "B": "Constructors cannot throw exceptions", "C": "The partially constructed object is still returned", "D": "Object creation fails, no reference is returned, and the caller must handle/declare the exception"}'::jsonb, 'D', 'If a constructor throws an exception, instantiation aborts and no reference to the incomplete object escapes.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'classes-objects'), '70000000-0000-0000-0000-000000000021'::uuid, 'In a static inner class (''static class Node'') vs a non-static inner class (''class Node''), what extra reference does the non-static inner class hold?', '{"A": "None", "B": "A reference to all sibling objects", "C": "An implicit synthetic reference to the enclosing outer instance (OuterClass.this)", "D": "A static reference to main()"}'::jsonb, 'C', 'Non-static inner classes capture an implicit reference to their outer instance, which can cause memory leaks if the inner object outlives the outer one.', 'ADVANCED', TRUE);

-- Skill: encapsulation
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'Which access modifier restricts visibility strictly to the declaring class itself?', '{"A": "public", "B": "default (package-private)", "C": "private", "D": "protected"}'::jsonb, 'C', 'private members are accessible only within the same top-level class.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'What is the visibility of a class member in Java when NO access modifier keyword is specified?', '{"A": "public", "B": "package-private (accessible to classes in the same package)", "C": "protected", "D": "private"}'::jsonb, 'B', 'Omitting an access modifier gives package-private (default) access.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'Which modifier makes a class or member accessible from any other package?', '{"A": "static", "B": "protected", "C": "public", "D": "private"}'::jsonb, 'C', 'public grants universal visibility across all packages.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000023'::uuid, 'Why does encapsulation recommend making fields private and exposing public getter/setter methods?', '{"A": "To make code longer", "B": "To hide internal representation and enforce validation before state changes", "C": "To prevent inheritance", "D": "Because private fields are faster"}'::jsonb, 'B', 'Getters and setters control access and allow validation invariants without breaking callers if internals change.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000023'::uuid, 'What naming convention is standard for a getter of a boolean field named ''active''?', '{"A": "active()", "B": "getActive() or isActive()", "C": "readActive()", "D": "fetchActive()"}'::jsonb, 'B', 'JavaBeans convention uses isActive() (or getActive()) for boolean properties.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000023'::uuid, 'What can a setter method do that direct public field assignment cannot?', '{"A": "Make a class static", "B": "Validate incoming values and reject invalid state (e.g., negative age)", "C": "Store primitives", "D": "Bypass type checking"}'::jsonb, 'B', 'Setters act as a gatekeeper to enforce invariants such as non-null or range checks.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'What does the ''final'' keyword do when applied to a variable?', '{"A": "Prevents the variable from being reassigned after initialization", "B": "Makes the object''s internal fields immutable", "C": "Allows the variable to be reassigned once later", "D": "Deletes the variable"}'::jsonb, 'A', 'final prevents reassignment of the variable itself (for references, it locks the pointer, not the object''s internal state).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'Which well-known Java standard library class is immutable?', '{"A": "HashMap", "B": "ArrayList", "C": "StringBuilder", "D": "String"}'::jsonb, 'D', 'String instances cannot be modified after creation.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'Which two scopes can access a ''protected'' member in Java?', '{"A": "Classes in the same package AND subclasses in any package", "B": "Only subclasses", "C": "Only the same class", "D": "Any class in the same module"}'::jsonb, 'A', 'protected allows access within the same package as well as from subclasses in different packages.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'Can a top-level Java class (not nested) be declared ''private'' or ''protected''?', '{"A": "Only private", "B": "No, top-level classes can only be public or package-private", "C": "Only protected", "D": "Yes, both"}'::jsonb, 'B', 'Top-level classes cannot be private or protected; only nested classes support all four visibility levels.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'Can two instances of the SAME class access each other''s ''private'' fields directly?', '{"A": "No, private is per-object", "B": "Only via reflection", "C": "Yes, access control in Java is class-based, not instance-based", "D": "Only if fields are static"}'::jsonb, 'C', 'Inside class User, code in method equals(User other) can directly read other.passwordHash because it is within the same class.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
