INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000023'::uuid, 'Why is returning an internal mutable ''List<String> tags'' directly from a getter an encapsulation leak?', '{"A": "Callers can call getTags().clear() or add() to mutate internal state bypassing validation", "B": "It slows down the JVM", "C": "Lists cannot be returned from methods", "D": "It causes a compile error"}'::jsonb, 'A', 'Returning a mutable reference lets callers modify internal state behind the class''s back; return Collections.unmodifiableList(...) or List.copyOf(...) instead.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'Which combination of rules is required to make a Java class truly immutable?', '{"A": "Use final on methods only", "B": "Declare the class final, make all fields private final, omit setters, and defensively copy mutable inputs/outputs", "C": "Only add private to fields", "D": "Make fields public and static"}'::jsonb, 'B', 'All four measures—final class, private final fields, no mutators, and defensive copying of mutable objects—guarantee immutability.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'What happens if you declare ''private final List<String> items = new ArrayList<>();'' and call ''items.add("x")''?', '{"A": "UnsupportedOperationException", "B": "items becomes null", "C": "Compile-time error because items is final", "D": "It succeeds: final prevents reassigning ''items'', not mutating the List object"}'::jsonb, 'D', 'final locks the reference binding, not the mutability of the referenced object.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'What is a defensive copy in an immutable class constructor?', '{"A": "Using try-catch around assignment", "B": "Cloning the entire JVM heap", "C": "Making a backup in a static field", "D": "Copying the input object (e.g., new Date(input.getTime()) or List.copyOf(input)) so caller mutations afterward don''t affect the object"}'::jsonb, 'D', 'Defensive copying isolates the class''s internal state from external references held by the caller.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'If a subclass in a different package accesses a ''protected'' field of its parent, which syntax is legal?', '{"A": "Accessing it on a parent-typed reference (Parent p = new Parent(); p.field)", "B": "Accessing it from an unrelated class in the child''s package", "C": "Neither", "D": "Accessing it on ''this'' or a subclass reference (this.field / child.field)"}'::jsonb, 'D', 'Across packages, protected members are only accessible through inheritance on the subclass type itself, not on an arbitrary parent instance.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000023'::uuid, 'Why can exposing ''public'' mutable fields hurt backward compatibility?', '{"A": "Public fields cannot be serialized", "B": "Public fields use more RAM", "C": "Public fields cannot hold objects", "D": "You cannot add validation, logging, or change the internal storage type later without breaking all callers"}'::jsonb, 'D', 'Encapsulating behind methods preserves the public contract while allowing internal implementation changes.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'How do Java ''record'' classes (Java 16+) enforce shallow immutability?', '{"A": "Records cannot hold List fields", "B": "Records store fields as Strings", "C": "Records automatically deep-clone every field", "D": "Records are implicitly final classes with private final fields and no setters, though mutable components still need defensive copies"}'::jsonb, 'D', 'Records generate private final fields and accessors, but if a component is a mutable List/Date, you should defensively copy in a compact constructor.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'Why are immutable objects inherently thread-safe?', '{"A": "Their state cannot change after construction, eliminating race conditions and need for synchronization", "B": "They cannot be shared between threads", "C": "The JVM stores them in CPU cache only", "D": "They automatically acquire synchronized locks"}'::jsonb, 'A', 'Without state mutation (assuming safe publication via final fields), multiple threads can read immutable objects concurrently without locks.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000024'::uuid, 'What guarantee does the Java Memory Model give for ''final'' fields in properly constructed objects (no ''this'' escape)?', '{"A": "None", "B": "Final fields are stored on the stack", "C": "Any thread seeing the object reference is guaranteed to see the initialized values of its final fields without extra synchronization", "D": "Final fields are volatile"}'::jsonb, 'C', 'JLS 17.5 guarantees freeze-action visibility for final fields when ''this'' does not escape during construction.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'In Java, when overriding a method in a subclass, what visibility rule applies?', '{"A": "Visibility must always change", "B": "You can keep the same or widen visibility (e.g., protected -> public), never narrow it", "C": "You can narrow visibility (e.g., public -> private)", "D": "All overridden methods must be protected"}'::jsonb, 'B', 'Liskov substitution requires a subclass method to be at least as accessible as the parent method it overrides.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000023'::uuid, 'In a defensive-copy constructor ''this.dates = new ArrayList<>(dates);'', why must you copy BEFORE validating or checking elements?', '{"A": "new ArrayList<>() sorts the list", "B": "It saves one allocation", "C": "Otherwise a concurrent thread could mutate the caller''s list between validation and copying (TOCTOU attack)", "D": "Validation throws an error on uncopied lists"}'::jsonb, 'C', 'Copy-then-validate prevents time-of-check to time-of-use (TOCTOU) race conditions from malicious or concurrent callers.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'encapsulation'), '70000000-0000-0000-0000-000000000022'::uuid, 'Why does ''private'' NOT prevent access via Java Reflection (''field.setAccessible(true)'') unless blocked by module boundaries?', '{"A": "Reflection only reads static fields", "B": "Reflection runs in C++", "C": "private is only enforced at compile time and standard access checks, which setAccessible(true) can bypass within open modules", "D": "private is identical to public at runtime"}'::jsonb, 'C', 'Java modules (JPMS) enforce strong encapsulation at runtime across modules, whereas traditional private can be bypassed by reflection if permitted.', 'ADVANCED', TRUE);

-- Skill: inheritance
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'Which keyword is used in Java for a class to inherit from another class?', '{"A": "extends", "B": "inherits", "C": "super", "D": "implements"}'::jsonb, 'A', 'A class uses ''extends'' to inherit fields and methods from a single superclass.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'What is the root superclass of every class in Java?', '{"A": "java.lang.System", "B": "java.lang.Class", "C": "java.lang.Object", "D": "java.lang.Base"}'::jsonb, 'C', 'Every class in Java implicitly or explicitly extends java.lang.Object.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'How many direct superclasses can a Java class extend?', '{"A": "Two", "B": "Zero", "C": "Unlimited", "D": "At most one (single class inheritance)"}'::jsonb, 'D', 'Java supports single inheritance for classes to avoid the diamond ambiguity problem; multiple inheritance is supported for interfaces.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'What does ''super()'' do inside a subclass constructor?', '{"A": "Invokes the constructor of the immediate parent class", "B": "Creates a new subclass instance", "C": "Deletes parent fields", "D": "Calls a static method"}'::jsonb, 'A', '''super(...)'' invokes the superclass constructor so inherited state is initialized first.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'How can a subclass invoke a parent class''s overridden method?', '{"A": "base.method()", "B": "super.method()", "C": "parent.method()", "D": "this.method()"}'::jsonb, 'B', '''super.method()'' explicitly invokes the superclass implementation.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'In a constructor hierarchy Parent -> Child, which constructor body finishes executing first?', '{"A": "Parent''s constructor", "B": "They finish in random order", "C": "Child''s constructor", "D": "Only Child runs"}'::jsonb, 'A', 'Superclass constructors always execute before the subclass constructor body.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'What annotation should be placed on an overridden method to catch signature typos at compile time?', '{"A": "@Super", "B": "@Overload", "C": "@Inherit", "D": "@Override"}'::jsonb, 'D', '@Override instructs the compiler to verify that the method actually overrides a superclass or interface method.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'Can a ''final'' method in a parent class be overridden by a subclass?', '{"A": "Only in the same package", "B": "No, declaring a method final prevents overriding", "C": "Only if public", "D": "Yes, with @Override"}'::jsonb, 'B', 'The ''final'' modifier on a method locks its implementation against overriding.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'Which inheritance relationship does ''class Car extends Vehicle'' represent?', '{"A": "IS-A relationship", "B": "PART-OF relationship", "C": "USES-A relationship", "D": "HAS-A relationship"}'::jsonb, 'A', 'Inheritance models an IS-A relationship (a Car IS-A Vehicle), whereas composition models HAS-A.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'Are ''private'' fields and methods of a superclass directly accessible by name inside a subclass?', '{"A": "Yes, always", "B": "Only private methods, not fields", "C": "No, private members are not directly accessible in subclasses", "D": "Only if the subclass is in the same package"}'::jsonb, 'C', 'Private members are encapsulated in the superclass and must be accessed via public/protected methods.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'What happens when you try to extend a class declared as ''final'' (e.g., ''class MyString extends String'')?', '{"A": "Runtime SecurityException", "B": "Compile-time error: cannot inherit from final class", "C": "It compiles normally", "D": "Creates a wrapper class"}'::jsonb, 'B', 'A ''final'' class cannot be subclassed.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'If a parent class defines ONLY a parameterized constructor ''Parent(int x)'' (no no-arg constructor), what happens in ''class Child extends Parent {}''?', '{"A": "Runtime error", "B": "Compiles fine", "C": "Compile-time error: Child''s implicit super() fails because Parent has no no-arg constructor", "D": "Child passes 0 automatically"}'::jsonb, 'C', 'Child must explicitly define a constructor calling ''super(someInt)''.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'Where must an explicit ''super(...)'' call appear inside a subclass constructor?', '{"A": "Anywhere in the constructor", "B": "Inside an if block", "C": "As the last statement", "D": "As the very first statement"}'::jsonb, 'D', 'super(...) (just like this(...)) must be the first statement of the constructor.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'What is a covariant return type in method overriding?', '{"A": "Changing int to long", "B": "Returning two different types", "C": "An overriding method returning a subtype of the return type declared by the overridden parent method", "D": "Returning void instead of int"}'::jsonb, 'C', 'For reference return types, an overriding method may return a more specific subclass (e.g., Dog instead of Animal).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'Can a subclass override a ''static'' method from its superclass?', '{"A": "Compile error", "B": "Only if @Override is added", "C": "Yes, runtime polymorphism applies", "D": "No, defining a static method with the same signature hides the parent method (method hiding), not overriding"}'::jsonb, 'D', 'Static methods are resolved at compile time based on reference type (method hiding), so @Override is rejected on static methods.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'When overriding a method, what checked-exception rule must the subclass method obey?', '{"A": "It can throw any new checked exception", "B": "It may throw the same, fewer, or narrower checked exceptions, never broader/new checked exceptions", "C": "It must throw Exception", "D": "It cannot throw any exceptions at all"}'::jsonb, 'B', 'Callers typed to the superclass only expect the superclass''s declared checked exceptions; unchecked RuntimeExceptions have no such restriction.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'Why is composition (''HAS-A'') often preferred over inheritance (''IS-A'') for code reuse?', '{"A": "Composition uses no interfaces", "B": "Inheritance doesn''t support methods", "C": "Composition avoids tight coupling to superclass internals and allows changing behavior at runtime", "D": "Inheritance is deprecated in Java"}'::jsonb, 'C', 'Favoring composition over inheritance avoids fragile base classes and lets components be swapped dynamically.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'Can ''super'' be used inside a ''static'' method of a subclass?', '{"A": "Only for static fields", "B": "Yes", "C": "Only in main()", "D": "No, super refers to the current instance''s superclass view and cannot be used in static context"}'::jsonb, 'D', 'Like ''this'', ''super'' requires an instance and is illegal in static methods or static initializers.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'If Parent''s constructor calls an overridable method ''init()'', and Child overrides ''init()'' to print a Child field initialized to ''hello'', what prints during ''new Child()''?', '{"A": "Compile-time error", "B": "null (or default 0), because Child''s field initializers haven''t run yet during Parent''s constructor", "C": "NullPointerException always", "D": "\"hello\""}'::jsonb, 'B', 'Parent''s constructor runs before Child''s field initializers; dynamic dispatch invokes Child.init() while Child''s fields still hold default zero/null values.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'What happens if Parent defines ''private void foo()'' and Child defines ''public void foo()''?', '{"A": "They are two completely independent methods because private methods are not inherited", "B": "Dynamic dispatch calls Child.foo() on Parent reference", "C": "Child overrides Parent.foo()", "D": "Compile-time error"}'::jsonb, 'A', 'Private methods are invisible to subclasses, so Child.foo() is a brand-new method; adding @Override would fail to compile.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'How are instance variables resolved when both Parent and Child declare a field with the same name ''int x''?', '{"A": "Parent''s field is deleted", "B": "Child overrides Parent''s field", "C": "Field hiding occurs: the field accessed depends on the compile-time reference type, not runtime object type", "D": "Compile-time error"}'::jsonb, 'C', 'Fields are not polymorphic in Java; ''Parent p = new Child(); p.x'' reads Parent.x while ''((Child) p).x'' reads Child.x.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000027'::uuid, 'Why is covariant return type allowed for reference types (Animal -> Dog) but NOT for primitives (double -> int)?', '{"A": "JVM bytecode forbids int returns", "B": "Primitives are final", "C": "int is larger than double", "D": "Primitives have no subtype/Liskov relationship in Java"}'::jsonb, 'D', 'Dog IS-A Animal, so callers expecting Animal can safely accept Dog; int is not a subtype of double.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000025'::uuid, 'In Java 17+, what does a ''sealed class Shape permits Circle, Rectangle'' declaration enforce?', '{"A": "Circle and Rectangle must be private", "B": "Only the explicitly listed classes in ''permits'' may directly extend Shape", "C": "Shape cannot have methods", "D": "Shape becomes an interface"}'::jsonb, 'B', 'Sealed classes restrict which classes/interfaces may extend or implement them, enabling exhaustive pattern matching.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'inheritance'), '70000000-0000-0000-0000-000000000026'::uuid, 'In ''Parent -> Child -> GrandChild'', can GrandChild write ''super.super.method()'' to bypass Child''s override?', '{"A": "Only if Parent''s method is static", "B": "Only in constructors", "C": "No, Java forbids super.super to preserve encapsulation of Child''s behavior", "D": "Yes"}'::jsonb, 'C', 'Bypassing an immediate superclass''s override would break invariants maintained by Child, so Java disallows super.super.', 'ADVANCED', TRUE);

-- Skill: polymorphism
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'Which form of polymorphism is resolved at compile time in Java?', '{"A": "Method overriding", "B": "Interface implementation", "C": "Dynamic dispatch", "D": "Method overloading"}'::jsonb, 'D', 'Method overloading is static/compile-time polymorphism; the compiler picks the overload based on argument types.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'Which form of polymorphism is resolved at runtime in Java?', '{"A": "Static method hiding", "B": "Method overloading", "C": "Constructor overloading", "D": "Method overriding"}'::jsonb, 'D', 'Method overriding uses runtime polymorphism (dynamic method dispatch) based on the actual object type.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'Does method overloading require inheritance?', '{"A": "No, overloaded methods usually live in the same class", "B": "Yes, always", "C": "Only for void methods", "D": "Only for static methods"}'::jsonb, 'A', 'Overloading occurs within a class (or across parent/child), whereas overriding strictly requires inheritance.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'What is upcasting in Java?', '{"A": "Assigning a subclass object to a superclass (or interface) reference", "B": "Converting a parent reference to a child reference", "C": "Converting int to double", "D": "Cloning an object"}'::jsonb, 'A', 'Upcasting (e.g., Animal a = new Dog();) is always safe and happens implicitly.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'Which operator safely checks whether an object reference is an instance of a specific class before downcasting?', '{"A": "castcheck", "B": "typeof", "C": "isType", "D": "instanceof"}'::jsonb, 'D', '''if (a instanceof Dog)'' tests the runtime type before performing a downcast.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'Does downcasting require an explicit cast in Java?', '{"A": "Yes, e.g., (Dog) animal", "B": "Only for Object", "C": "No, it is implicit", "D": "Only for interfaces"}'::jsonb, 'A', 'Because a parent reference might not actually hold the child type, downcasting requires an explicit cast.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'In ''Animal a = new Dog(); a.speak();'', where Dog overrides speak(), which speak() executes?', '{"A": "Dog.speak()", "B": "Compile-time error", "C": "Animal.speak()", "D": "Both"}'::jsonb, 'A', 'Dynamic dispatch invokes the method of the actual runtime object (Dog), not the reference type (Animal).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'Why is polymorphism useful when working with collections like ''List<Shape>''?', '{"A": "It makes all Shapes have the same fields", "B": "It prevents adding elements", "C": "You can iterate and call shape.draw() uniformly without knowing each concrete subclass", "D": "It eliminates constructors"}'::jsonb, 'C', 'Client code programs against the supertype contract and automatically dispatches to each concrete subtype''s behavior.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'If Parent has ''void show(Object o)'' and Child adds ''void show(String s)'', is Child overriding or overloading?', '{"A": "Method hiding", "B": "Overloading, because the parameter types differ", "C": "Overriding", "D": "Compile error"}'::jsonb, 'B', 'Because Object and String are different parameter types, Child introduces an overload rather than overriding Parent''s method.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'Which statement compares parameters and return types in overloading vs overriding?', '{"A": "Overriding changes parameters; overloading keeps them identical", "B": "Both must change return types", "C": "Both must keep parameters identical", "D": "Overloading changes parameters; overriding keeps the exact same parameter list"}'::jsonb, 'D', 'Overloading requires different parameter lists; overriding requires matching name and parameter list.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'Given ''Animal a = new Cat(); Dog d = (Dog) a;'', what happens at compile time and runtime?', '{"A": "Succeeds and returns null", "B": "Converts Cat to Dog", "C": "Compiles cleanly, then throws ClassCastException at runtime", "D": "Compile-time error"}'::jsonb, 'C', 'Because Animal is a supertype of Dog, the compiler allows the cast, but at runtime the object is a Cat so ClassCastException is thrown.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'When using an upcast reference ''Animal a = new Dog();'', can you call a method ''fetch()'' that is defined ONLY on Dog?', '{"A": "Yes, because the runtime object is Dog", "B": "Yes, if fetch() is public", "C": "Only if Dog is final", "D": "No, the compiler only allows methods declared on the compile-time reference type Animal"}'::jsonb, 'D', 'Compile-time type checking restricts method calls to members known on the reference type (Animal).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'How does pattern matching for instanceof (Java 16+) simplify downcasting?', '{"A": "It replaces all if statements", "B": "It disables ClassCastException everywhere", "C": "It automatically converts any object to String", "D": "''if (obj instanceof String s)'' checks the type and binds ''s'' in one step without an explicit cast"}'::jsonb, 'D', 'Pattern matching eliminates the redundant ''(String) obj'' cast after the instanceof check.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'What happens with ''Parent p = new Child(); p.staticMethod();''?', '{"A": "Child.staticMethod() runs", "B": "Compile error", "C": "Both run", "D": "Parent.staticMethod() runs, because static methods are bound at compile time, not dynamically dispatched"}'::jsonb, 'D', 'Static methods use static binding (based on reference type Parent), not virtual method dispatch.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'What does ''null instanceof String'' evaluate to in Java?', '{"A": "true", "B": "Throws NullPointerException", "C": "Compile-time error", "D": "false"}'::jsonb, 'D', 'null is not an instance of any type, so ''null instanceof Anything'' safely returns false.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'How does the JVM implement dynamic dispatch for normal instance methods?', '{"A": "Using reflection on every call", "B": "By recompiling bytecode on each call", "C": "By searching source files", "D": "Using virtual method tables (vtables) associated with each class''s runtime metadata"}'::jsonb, 'D', 'The invokevirtual bytecode instruction dispatches via the object''s class vtable to the overridden method.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'Why does ''String s = (String) Integer.valueOf(5);'' fail at compile time rather than runtime?', '{"A": "String cannot be cast", "B": "Integer is final and cannot have subclasses, so the compiler knows it can never be a String", "C": "All casts fail at compile time", "D": "5 is too small"}'::jsonb, 'B', 'The compiler rejects casts between unrelated types in the class hierarchy when neither can be a subtype of the other.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'If Parent defines ''void process(Number n)'' and Child overrides ''void process(Number n)'' and ALSO overloads ''void process(Integer i)'', which runs for ''Parent p = new Child(); p.process(Integer.valueOf(1));''?', '{"A": "Child.process(Integer)", "B": "Child.process(Number)", "C": "Parent.process(Number)", "D": "Compile error"}'::jsonb, 'B', 'Compile-time overload resolution sees reference type Parent, which only has process(Number); at runtime, dynamic dispatch invokes Child''s override of process(Number).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'In Java, why is dynamic dispatch called ''single dispatch'' rather than ''double dispatch''?', '{"A": "It cannot be used in interfaces", "B": "It dispatches based only on the runtime type of the receiver (''this''), while overloaded argument types are chosen statically at compile time", "C": "It only works with one parameter", "D": "It dispatches once per JVM startup"}'::jsonb, 'B', 'Single dispatch picks the method at runtime using only the receiver object''s class; the Visitor pattern simulates double dispatch.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'How do you handle a case where an object implements two interfaces that both declare a method ''void run()'' with the same signature?', '{"A": "One implementation satisfies both interfaces unless they have incompatible return types", "B": "You must write two separate methods", "C": "Java chooses randomly", "D": "Compilation always fails"}'::jsonb, 'A', 'If both interface methods share the same signature and compatible return types, a single implementation satisfies both.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'When can the JIT compiler devirtualize a polymorphic ''invokevirtual'' call?', '{"A": "Only when @Inline is present", "B": "Never", "C": "Only for static methods", "D": "When class hierarchy analysis shows only one concrete implementation is loaded (monomorphic call site), allowing inlining"}'::jsonb, 'D', 'HotSpot''s JIT tracks receiver types at call sites and speculatively inlines monomorphic/bimorphic calls with a fast type guard.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000029'::uuid, 'Why is ''List<Dog>'' NOT a subtype of ''List<Animal>'' in Java even though ''Dog[]'' IS a subtype of ''Animal[]''?', '{"A": "Generics don''t support inheritance", "B": "Generics are invariant to guarantee compile-time type safety (preventing putting a Cat into a List<Dog>)", "C": "Animal cannot be used in List", "D": "List is final"}'::jsonb, 'B', 'Generic invariance catches heterogeneous-insertion errors at compile time; use wildcards like ''List<? extends Animal>'' when covariance is needed.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000028'::uuid, 'If Parent defines ''Object get()'' and Child overrides ''String get()'', what synthetic method does javac generate in Child''s bytecode?', '{"A": "A synthetic bridge method ''Object get()'' that delegates to ''String get()'' so JVM binary compatibility holds", "B": "A static helper", "C": "An abstract method", "D": "None"}'::jsonb, 'A', 'At the JVM bytecode level, return types are part of the method descriptor, so javac emits a bridge method to preserve polymorphism.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'polymorphism'), '70000000-0000-0000-0000-000000000030'::uuid, 'In ''class A { private void f() { System.out.print("A"); } public static void main(String[] args) { A a = new B(); a.f(); } } class B extends A { public void f() { System.out.print("B"); } }'', what prints?', '{"A": "A", "B": "B", "C": "AB", "D": "Compile error"}'::jsonb, 'A', 'Because main() is inside class A, ''a.f()'' resolves statically (invokespecial) to A''s private f(), printing ''A'' without dynamic dispatch.', 'ADVANCED', TRUE);

-- Skill: abstraction-interfaces
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'Can an ''abstract'' class be instantiated directly using ''new AbstractClass()''?', '{"A": "Only inside static methods", "B": "No, abstract classes cannot be directly instantiated", "C": "Yes", "D": "Yes, if it has no abstract methods"}'::jsonb, 'B', 'Abstract classes must be subclassed by a concrete class (or anonymous subclass) to be instantiated.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'Can an abstract class contain concrete (fully implemented) methods and instance fields?', '{"A": "No, only abstract methods", "B": "Only static methods", "C": "Only constants", "D": "Yes, it can mix abstract methods, concrete methods, constructors, and instance fields"}'::jsonb, 'D', 'Abstract classes can provide shared state and partial implementation alongside abstract methods.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'What happens if a concrete (non-abstract) subclass extends an abstract class without implementing all its abstract methods?', '{"A": "The missing methods default to doing nothing", "B": "Compile-time error unless the subclass is also declared abstract", "C": "Runtime AbstractMethodError", "D": "JVM ignores them"}'::jsonb, 'B', 'A concrete subclass must implement every inherited abstract method.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'Which keyword does a class use to adopt an interface contract?', '{"A": "adopts", "B": "extends", "C": "implements", "D": "uses"}'::jsonb, 'C', 'Classes use ''implements'' (and may implement multiple comma-separated interfaces).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'What are the implicit modifiers on variables declared inside a Java interface?', '{"A": "package-private mutable", "B": "protected", "C": "public static final (constants)", "D": "private final"}'::jsonb, 'C', 'Interface fields are always implicitly public, static, and final constants.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'How many interfaces can a single Java class implement?', '{"A": "At most two", "B": "At most one", "C": "Any number (multiple interfaces)", "D": "Only if the class is abstract"}'::jsonb, 'C', 'Java supports multiple interface implementation: ''class Foo implements A, B, C''.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'Which keyword allows an interface to provide a method body that implementing classes automatically inherit?', '{"A": "default", "B": "abstract", "C": "virtual", "D": "concrete"}'::jsonb, 'A', 'Introduced in Java 8, ''default'' methods allow interfaces to evolve without breaking existing implementations.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'What defines a Functional Interface in Java?', '{"A": "An interface with exactly one abstract method (SAM)", "B": "An interface with only static methods", "C": "An interface with no methods", "D": "Any interface with @Override"}'::jsonb, 'A', 'A functional interface has a single abstract method (plus any number of default/static/Object methods) and can be targeted by lambdas.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'Can an abstract class have a constructor, and when does it execute?', '{"A": "Yes; it runs when a concrete subclass is instantiated via super()", "B": "Only if the constructor is static", "C": "No, abstract classes cannot have constructors", "D": "Only when called directly with new"}'::jsonb, 'A', 'Abstract classes use constructors to initialize their own fields when a subclass calls super().', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'When should you choose an abstract class over an interface?', '{"A": "When unrelated classes need a shared capability", "B": "When you need multiple inheritance of type", "C": "Whenever you want lambdas", "D": "When closely related classes share mutable state (instance fields) and common code"}'::jsonb, 'D', 'Abstract classes suit IS-A hierarchies with shared instance state; interfaces suit capabilities across unrelated classes.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'What happens if a method is declared ''abstract'' and ''private'' (or ''final'') together?', '{"A": "Compile-time error: an abstract method must be overridable by subclasses", "B": "It acts as a static method", "C": "It compiles normally", "D": "Runtime error"}'::jsonb, 'A', 'private/final/static prevent overriding, which contradicts the purpose of abstract.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'What keyword does one interface use to inherit from another interface?', '{"A": "super", "B": "implements", "C": "extends", "D": "inherits"}'::jsonb, 'C', 'An interface ''extends'' one or more parent interfaces.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'What visibility must an implementing class give to methods declared in an interface?', '{"A": "public, because interface methods are implicitly public", "B": "package-private", "C": "Any visibility", "D": "protected"}'::jsonb, 'A', 'Because interface methods are implicitly public, implementing classes cannot narrow them to protected or package-private.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'What happens if a class implements two interfaces A and B that both define a ''default void log()'' method?', '{"A": "Compile-time error unless the class overrides log() to resolve the conflict", "B": "Java picks A automatically", "C": "Runtime ambiguity exception", "D": "Both run in order"}'::jsonb, 'A', 'The implementing class must override log() and may explicitly delegate via ''A.super.log()'' if desired.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'Are ''static'' methods in an interface inherited by implementing classes?', '{"A": "Only if marked default", "B": "No; interface static methods must be called on the interface name itself (InterfaceName.method())", "C": "Yes, via ClassName.staticMethod()", "D": "Interfaces cannot have static methods"}'::jsonb, 'B', 'Unlike class static methods, interface static methods are never inherited by implementing classes or sub-interfaces.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'What is the purpose of the ''@FunctionalInterface'' annotation?', '{"A": "It generates a default constructor", "B": "It is optional, but causes the compiler to verify the interface has exactly one abstract method", "C": "It is required for lambdas to work", "D": "It makes methods thread-safe"}'::jsonb, 'B', 'Any single-abstract-method interface works with lambdas, and @FunctionalInterface guards against accidentally adding a second abstract method.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'Can a Java interface contain ''private'' helper methods (Java 9+)?', '{"A": "Only if sealed", "B": "Yes, to share common logic between default or static methods inside the interface", "C": "Only abstract private methods", "D": "No, all interface methods are public"}'::jsonb, 'B', 'Java 9 introduced private (and private static) methods in interfaces to avoid duplicating helper code across default methods.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'What is a marker interface (such as Serializable or Cloneable)?', '{"A": "An annotation", "B": "An abstract class with no fields", "C": "An empty interface with no methods used to tag classes with metadata/capability", "D": "An interface with 10+ methods"}'::jsonb, 'C', 'Marker interfaces carry type-level metadata checked via instanceof or runtime APIs.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'If class C extends class P (which defines concrete ''void m()'') and also implements interface I (which defines ''default void m()''), which ''m()'' wins?', '{"A": "Superclass P''s concrete method (''class wins'' rule)", "B": "Compile error: conflict", "C": "Interface I''s default method", "D": "Throws AmbiguousMethodException"}'::jsonb, 'A', 'Java''s default-method resolution rule #1 (''classes win'') gives a superclass concrete method priority over interface default methods.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'If interface B extends interface A and both declare ''default void m()'', and class C implements both A and B without overriding m(), which runs?', '{"A": "Both", "B": "Compile error: conflict", "C": "A.m()", "D": "B.m(), because the more specific sub-interface wins"}'::jsonb, 'D', 'Rule #2 (''sub-interfaces win''): when one interface extends another, the more specific default method is selected.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'Can an interface declare a ''default'' method that overrides ''equals'', ''hashCode'', or ''toString'' from java.lang.Object?', '{"A": "Only if static", "B": "No, compile-time error: default methods cannot override Object methods", "C": "Only toString()", "D": "Yes"}'::jsonb, 'B', 'Every class already inherits Object''s methods, and because ''classes win'', an interface default Object method could never win—so Java forbids it.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000033'::uuid, 'Why does ''interface MyFunc { void run(); boolean equals(Object o); }'' still qualify as a Functional Interface?', '{"A": "It has two abstract methods so it does not", "B": "Abstract methods matching public methods of java.lang.Object do not count toward the single-abstract-method limit", "C": "equals() is treated as default", "D": "Only void methods count"}'::jsonb, 'B', 'JLS 9.8 excludes public Object methods (equals, hashCode, toString) from the SAM count because every class already implements them.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000032'::uuid, 'How does the Dependency Inversion Principle (DIP) leverage interfaces in Spring / backend design?', '{"A": "High-level services depend on abstractions (interfaces) rather than concrete implementations, enabling swapping and mocking", "B": "Interfaces depend on SQL tables", "C": "All classes are made final", "D": "Services instantiate repositories with ''new''"}'::jsonb, 'A', 'Programming to interfaces decouples business logic from concrete persistence or HTTP implementations.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'abstraction-interfaces'), '70000000-0000-0000-0000-000000000031'::uuid, 'In an abstract class implementing the Template Method design pattern, why is the template method itself often declared ''final''?', '{"A": "To prevent subclasses from altering the overall algorithm skeleton while allowing them to override specific abstract hook steps", "B": "To allow multiple inheritance", "C": "Because abstract classes cannot have non-final methods", "D": "To make it static"}'::jsonb, 'A', 'Making the template method final locks the sequence of steps while subclasses customize individual hook methods.', 'ADVANCED', TRUE);
